codeSample:
POST /fare -> Fare
Body: { pickupLocation, destination }
// 响应体创建并返回一条新的 Fare 记录，供后续 POST /rides 引用

POST /drivers/location
Authorization: Bearer <JWT>
Body: { lat, long }
// driverId 从 JWT payload 解出，不信任 body 里的任何身份字段

POST /rides -> Ride
Body: { fareId }
// 起终点、价格已存在 Fare 记录里；userId 来自会话，不需要客户端重复传

PATCH /rides/:rideId
Body: { action: "accept" }
// 响应: { rideId, status: "accepted", pickup, destination }

GEOADD drivers -122.27 37.80 driver:42
GEOSEARCH drivers FROMLONLAT -122.27 37.80 BYRADIUS 5 km ASC
// 经度写在纬度前面；ASC 按距离由近到远排序

ZADD driver_last_seen 1700000010 driver:42
// cleanup job:
ZRANGEBYSCORE driver_last_seen -inf (now-30)
// 逐个 ZREM driver_last_seen 和 ZREM drivers 对应成员

SET lock:driver:42 rideId123 NX EX 10
// NX: 只在锁不存在时设置；EX 10: 10 秒后自动过期
// 接受则 DEL lock:driver:42 释放；超时则 TTL 自动清除

consumer.poll()
// ... 处理匹配逻辑 ...
if (matched) consumer.commitSync({ [partition]: offset + 1 })
// 未匹配成功前绝不提交，崩溃后重启的消费者会重新拿到这条消息

sqs.sendMessage({
  QueueUrl: delayQueueUrl,
  DelaySeconds: 10,
  MessageBody: JSON.stringify({ rideId, driverId })
})
// 到期后 worker 检查 ride 是否仍 requested，未分配才顺延
